/**
 * Regression tests for Fix A — review/QA gate hygiene must not fail on build
 * artifacts a reviewer regenerated by re-running tests.
 *
 * Symptom (2026-06-02, agnt2-prototype-g3-terminal-integration HYGIENE_FAIL):
 * the codex /review gate re-ran `forge test`, which regenerated
 * `snapshots/ComposeTypedVmTest.json` and `contracts/deployments/*.json` with
 * new gas/deployment numbers. The gate's auto-commit refused them as "non-test
 * paths" and the phase failed with "reviewer edited production paths anyway".
 *
 * Fix: `cleanupReviewGeneratedArtifacts` restores dirty paths matching the
 * review generated-globs (defaults: snapshots/, broadcast/, .gas-snapshot;
 * plus `GSTACK_REVIEW_GENERATED_GLOBS`) to their committed version BEFORE the
 * gate hygiene check, so the canonical impl-committed version survives and the
 * gate sees a clean tree for those paths. Real source edits still fail.
 */

import { describe, it, expect, beforeEach, afterEach } from "bun:test";
import * as fs from "node:fs";
import * as os from "node:os";
import * as path from "node:path";
import { spawnSync } from "node:child_process";
import {
  resolveReviewGeneratedGlobs,
  cleanupReviewGeneratedArtifacts,
} from "../cli";

const cliPath = path.resolve(import.meta.dir, "../cli.ts");
const cliContent = fs.readFileSync(cliPath, "utf-8");

let tmpRoot: string;
let cwd: string;

function git(...args: string[]): { status: number | null; stdout: string } {
  const r = spawnSync("git", args, { cwd, encoding: "utf8" });
  return { status: r.status, stdout: r.stdout || "" };
}

beforeEach(() => {
  tmpRoot = fs.mkdtempSync(path.join(os.tmpdir(), "rggg-"));
  cwd = path.join(tmpRoot, "wt");
  fs.mkdirSync(cwd);
  git("init", "-b", "main");
  git("config", "user.email", "t@e.com");
  git("config", "user.name", "t");
  fs.mkdirSync(path.join(cwd, "snapshots"), { recursive: true });
  fs.mkdirSync(path.join(cwd, "src"), { recursive: true });
  fs.mkdirSync(path.join(cwd, "contracts", "deployments"), { recursive: true });
  fs.writeFileSync(path.join(cwd, "snapshots", "Foo.json"), '{"gas": 1}\n');
  fs.writeFileSync(path.join(cwd, "src", "Bar.sol"), "contract Bar {}\n");
  fs.writeFileSync(
    path.join(cwd, "contracts", "deployments", "base.planned.json"),
    '{"addr": "0x1"}\n',
  );
  git("add", "-A");
  git("commit", "-m", "seed");
});

afterEach(() => {
  delete process.env.GSTACK_REVIEW_GENERATED_GLOBS;
  try {
    fs.rmSync(tmpRoot, { recursive: true, force: true });
  } catch {}
});

describe("resolveReviewGeneratedGlobs", () => {
  it("T-A1: includes safe defaults (snapshots/broadcast/.gas-snapshot)", () => {
    const globs = resolveReviewGeneratedGlobs();
    expect(globs).toContain("**/snapshots/**/*");
    expect(globs).toContain("**/broadcast/**/*");
    expect(globs).toContain("**/.gas-snapshot");
  });

  it("T-A2: appends env globs and normalizes a bare `dir/**` to `dir/**/*`", () => {
    process.env.GSTACK_REVIEW_GENERATED_GLOBS =
      "**/contracts/deployments/** , **/out/*.json";
    const globs = resolveReviewGeneratedGlobs();
    expect(globs).toContain("**/contracts/deployments/**/*"); // normalized
    expect(globs).toContain("**/out/*.json"); // left as-is
  });
});

describe("cleanupReviewGeneratedArtifacts", () => {
  it("T-A3: restores a regenerated snapshot but leaves real source dirty", () => {
    // Reviewer re-ran tests: snapshot changed (regenerated) AND a real source
    // file was edited.
    fs.writeFileSync(path.join(cwd, "snapshots", "Foo.json"), '{"gas": 999}\n');
    fs.writeFileSync(path.join(cwd, "src", "Bar.sol"), "contract Bar { uint x; }\n");

    const cleaned = cleanupReviewGeneratedArtifacts(cwd);

    expect(cleaned).toContain("snapshots/Foo.json");
    // snapshot restored to committed version
    expect(fs.readFileSync(path.join(cwd, "snapshots", "Foo.json"), "utf8")).toBe(
      '{"gas": 1}\n',
    );
    // real source edit untouched — still dirty, gate will (correctly) catch it
    const status = git("status", "--porcelain").stdout;
    expect(status).toContain("src/Bar.sol");
    expect(status).not.toContain("snapshots/Foo.json");
  });

  it("T-A4: removes an UNTRACKED generated artifact", () => {
    fs.writeFileSync(path.join(cwd, "snapshots", "New.json"), '{"gas": 5}\n');
    const cleaned = cleanupReviewGeneratedArtifacts(cwd);
    expect(cleaned).toContain("snapshots/New.json");
    expect(fs.existsSync(path.join(cwd, "snapshots", "New.json"))).toBe(false);
  });

  it("T-A5: env-configured deployment globs are restored; without config they are NOT", () => {
    fs.writeFileSync(
      path.join(cwd, "contracts", "deployments", "base.planned.json"),
      '{"addr": "0xDEAD"}\n',
    );
    // Without config: deployment JSON is NOT a default generated path.
    const noConfig = cleanupReviewGeneratedArtifacts(cwd);
    expect(noConfig).not.toContain("contracts/deployments/base.planned.json");
    expect(
      git("status", "--porcelain").stdout,
    ).toContain("contracts/deployments/base.planned.json");

    // With per-project config: it IS restored.
    process.env.GSTACK_REVIEW_GENERATED_GLOBS = "**/contracts/deployments/**";
    const withConfig = cleanupReviewGeneratedArtifacts(cwd);
    expect(withConfig).toContain("contracts/deployments/base.planned.json");
    expect(
      git("status", "--porcelain").stdout,
    ).not.toContain("contracts/deployments/base.planned.json");
  });

  it("T-A6: a clean tree (no generated dirt) cleans nothing", () => {
    expect(cleanupReviewGeneratedArtifacts(cwd)).toEqual([]);
  });
});

describe("Fix A — static-grep wiring", () => {
  it("T-A7: applyGateHygiene restores review-generated artifacts (gated on isGateRole) before the hygiene check", () => {
    // A refactor that drops the cleanup call would re-introduce the wedge.
    expect(cliContent).toMatch(
      /if\s*\(isGateRole\)\s*\{[\s\S]{0,300}cleanupReviewGeneratedArtifacts\(opts\.cwd\)/,
    );
    expect(cliContent).toContain("DEFAULT_REVIEW_GENERATED_GLOBS");
    expect(cliContent).toContain("GSTACK_REVIEW_GENERATED_GLOBS");
  });
});
